// works against any leeway-DML class that structurally satisfies
// TaskCreatedEntityI.
func (c *TaskCreatedColumns) Marshal(w io.Writer) (err error) {
	ent := taskCreatedPool.Get().(*cbdml.InEntityFacts)
	defer taskCreatedPool.Put(ent)
	ent.SetActiveSections(TaskCreatedActiveSections)
	ent.Builder().SetActiveFields(TaskCreatedActiveFields())
	err = TaskCreatedBuildEntities(ent, c)
	if err != nil {
		return
	}
	var recs []*arrowrowcbor.Record
	recs, err = ent.TransferRecords(nil)
	if err != nil {
		err = eh.Errorf("taskcreated: transfer records: %w", err)
		return
	}
	rb := arrowrowcbor.JoinRecords(recs)
	_, err = w.Write(rb)
	if err != nil {
		err = eh.Errorf("taskcreated: marshal write: %w", err)
	}
	return
}

